Certainly! The Stoer-Wagner algorithm is an efficient method for finding the minimum cut of an undirected graph. Below is a sample implementation of the Stoer-Wagner algorithm in Swift.

### Swift Implementation of the Stoer-Wagner Algorithm:

```swift
import Foundation

class StoerWagner {
    var graph: [[Int]] // Adjacency matrix representation of the graph
    var n: Int // Number of vertices in the graph

    init(graph: [[Int]]) {
        self.graph = graph
        self.n = graph.count
    }

    func minCut() -> Int {
        var minCutValue = Int.max

        var vertices = Array(0..<n) // List of vertices

        // While there is more than one vertex in the graph
        while vertices.count > 1 {
            let (lastAdded, cutValue) = phase(vertices: &vertices)
            minCutValue = min(minCutValue, cutValue)
            // Combine the last two added vertices
            combine(lastAdded: lastAdded, vertices: &vertices)
        }

        return minCutValue
    }

    private func phase(vertices: inout [Int]) -> (Int, Int) {
        var A = Set<Int>() // Set of vertices in set A
        var weights = [Int](repeating: 0, count: n) // Weights for each vertex
        var lastAdded = -1

        while !vertices.isEmpty {
            // Find the most tightly connected vertex
            var maxWeight = -1
            for v in vertices {
                if A.contains(v) { continue }
                weights[v] += graph[lastAdded][v]
                if weights[v] > maxWeight {
                    maxWeight = weights[v]
                    lastAdded = v
                }
            }

            // Add the vertex to set A
            A.insert(lastAdded)
            vertices.removeAll { $0 == lastAdded }
        }

        // Calculate the cut value
        var cutValue = 0
        for i in A {
            for j in vertices {
                cutValue += graph[i][j]
            }
        }

        return (lastAdded, cutValue)
    }

    private func combine(lastAdded: Int, vertices: inout [Int]) {
        // Identify the vertex to combine with
        let index = vertices.firstIndex(of: lastAdded)!
        let combinedVertex = vertices[index]

        // Assume the next vertex to merge (there's always at least two vertices since we are combining).
        let otherVertex = vertices[index + 1 < vertices.count ? index + 1 : index - 1]

        // Update the graph
        for k in 0..<n {
            if k != combinedVertex && k != otherVertex {
                graph[otherVertex][k] += graph[combinedVertex][k]
                graph[k][otherVertex] += graph[k][combinedVertex]
            }
        }

        // Remove the combined vertex
        vertices.removeAll { $0 == combinedVertex }
    }
}

// Example usage:
let graph = [
    [0, 16, 13, 0, 0, 0],
    [16, 0, 10, 12, 0, 0],
    [13, 10, 0, 0, 14, 0],
    [0, 12, 0, 0, 0, 20],
    [0, 0, 14, 0, 0, 4],
    [0, 0, 0, 20, 4, 0]
]

let stoerWagner = StoerWagner(graph: graph)
let minCutValue = stoerWagner.minCut()
print("The minimum cut of the graph is: \(minCutValue)")
```

### Explanation:
1. **Graph Representation**: The graph is represented as an adjacency matrix, where each entry `graph[i][j]` indicates the weight of the edge connecting vertex `i` to vertex `j`.

2. **Initialization**: The `StoerWagner` class initializes the graph and the number of vertices.

3. **Finding Minimum Cut**: The method `minCut` repeatedly calls `phase` to find the most tightly connected vertex until all vertices are processed.

4. **Combining Vertices**: The `combine` method merges the last added vertex with another, updating the graph accordingly.

5. **Usage Example**: The example graph displays the minimum cut value, demonstrating how to use the functionality.

Feel free to modify the graph representation and test various configurations!

