### TCP Client Implementation in Unity

1. Create a new C# script in Unity and name it `TCPClientExample`.

```csharp
using System;
using System.Net.Sockets;
using System.Text;
using UnityEngine;

public class TCPClientExample : MonoBehaviour
{
    private TcpClient client;
    private NetworkStream stream;

    void Start()
    {
        ConnectToServer("127.0.0.1", 8080); // Change to your server's IP and port
    }

    void ConnectToServer(string ip, int port)
    {
        try
        {
            client = new TcpClient(ip, port);
            stream = client.GetStream();
            SendMessage("Hello Server!");
        }
        catch (Exception e)
        {
            Debug.Log("Error: " + e.Message);
        }
    }

    void SendMessage(string message)
    {
        if (stream != null && stream.CanWrite)
        {
            byte[] data = Encoding.ASCII.GetBytes(message);
            stream.Write(data, 0, data.Length);
            Debug.Log("Sent: " + message);
        }
    }

    private void OnApplicationQuit()
    {
        stream.Close();
        client.Close();
    }
}
```

### Instructions to Use

