```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    // Number of worker threads
    private const int WorkerCount = 32;
    private static SemaphoreSlim semaphore = new SemaphoreSlim(WorkerCount);
    private static List<Task> workerTasks = new List<Task>();
    private static bool isShutdown = false;

    static void Main(string[] args)
    {
        string filePath = "path/to/your/textfile.txt";

        // Starting worker threads
        for (int i = 0; i < WorkerCount; i++)
        {
            workerTasks.Add(Task.Run(() => Worker()));
        }

        // Iterate lines in the main thread
        foreach (var line in File.ReadLines(filePath))
        {
            semaphore.Wait(); // Wait for an available worker
            Task.Run(() => ProcessLine(line)); // Process the line in a worker thread
        }

        // Wait for all workers to finish processing
        isShutdown = true; // Signal workers to shutdown

        // Allow workers to process any remaining lines
        foreach (var task in workerTasks)
        {
            task.Wait(); 
        }

        Console.WriteLine("All processing complete.");
    }

    private static void ProcessLine(string line)
    {
        try
        {
            // Simulate processing the line
            Console.WriteLine($"Processing: {line}");
            Thread.Sleep(100); // Simulated work

            // After completing work, release the semaphore
        }
        finally
        {
            semaphore.Release(); // Release the semaphore slot
        }
    }

    private static void Worker()
    {
        while (!isShutdown)
        {
            // Just sit here until there is work. 
            // Line processing is done in Task.Run in the main thread loop.
        }
    }
}
```

