Sure! Below is a Python implementation of a console-based Tic-Tac-Toe game as per your requirements.

```python
def print_board(board):
    for row in board:
        print(" | ".join(row))
        print("-" * 9)

def check_winner(board):
    # Check rows, columns, and diagonals
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] != " ":
            return board[i][0]  # Row winner
        if board[0][i] == board[1][i] == board[2][i] != " ":
            return board[0][i]  # Column winner

    if board[0][0] == board[1][1] == board[2][2] != " ":
        return board[0][0]  # Diagonal winner (left to right)
    if board[0][2] == board[1][1] == board[2][0] != " ":
        return board[0][2]  # Diagonal winner (right to left)

    return None  # No winner yet

def is_board_full(board):
    return all(cell != " " for row in board for cell in row)

def main():
    # Initialize game board
    board = [[" " for _ in range(3)] for _ in range(3)]

    current_player = "X"  # Start with player X

    while True:
        print_board(board)

        # Get player input
        try:
            row = int(input(f"Player {current_player}, enter the row (0-2): "))
            col = int(input(f"Player {current_player}, enter the column (0-2): "))

            if board[row][col] != " ":
                print("This spot is already taken. Try again.")
                continue

            board[row][col] = current_player

            winner = check_winner(board)
            if winner:
                print_board(board)
                print(f"Player {winner} wins!")
                break

            if is_board_full(board):
                print_board(board)
                print("It's a draw!")
                break

            # Switch players
            current_player = "O" if current_player == "X" else "X"

        except (IndexError, ValueError):
            print("Invalid input. Please enter numbers between 0 and 2.")

if __name__ == "__main__":
    main()
